const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Approximate location of Bay Dosgris, south of New Orleans.
  // Using a point and buffering it to define an area of interest (AOI).
  const bayDosgrisPoint = ee.Geometry.Point([-89.96, 29.23]); // Centroid in the region
  const aoi = bayDosgrisPoint.buffer(5000).bounds(); // 5km buffer, then get its bounding box

  const startYear1 = '1985-01-01';
  const endYear1 = '1985-12-31';

  const startYear2 = '2023-01-01'; // Using 2023 as 2024 might have limited data, but let's try 2024 first.
  const endYear2 = '2024-05-31'; // Up to current date for 2024. If data is too sparse, will fallback to 2023.

  const scale = 30; // Landsat resolution

  // Function to mask clouds for Landsat 5
  function maskL5Clouds(image) {
    const qa = image.select('pixel_qa');
    const cloudState = qa.bitwiseAnd(1 << 5).eq(0); // Clear pixel
    const cloudShadowState = qa.bitwiseAnd(1 << 3).eq(0); // Not cloud shadow
    const snowState = qa.bitwiseAnd(1 << 4).eq(0); // Not snow
    const waterState = qa.bitwiseAnd(1 << 2).eq(0); // Not water (this is to mask water initially for land analysis, but we need water, so let's remove this for water detection)
    return image.updateMask(cloudState.and(cloudShadowState).and(snowState));
  }

  // Function to mask clouds for Landsat 8/9
  function maskL89Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const dilatedCloud = qa.bitwiseAnd(1 << 1).neq(0); // Dilated Cloud
    const cirrus = qa.bitwiseAnd(1 << 2).neq(0); // Cirrus
    const cloud = qa.bitwiseAnd(1 << 3).neq(0); // Cloud
    const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0); // Cloud Shadow

    // Combine masks
    const mask = dilatedCloud.or(cirrus).or(cloud).or(cloudShadow).not();
    return image.updateMask(mask);
  }

  // Function to calculate MNDWI and classify water
  function addMNDWIAndWater(image) {
    // For Landsat 5, bands are B2 (Green), B5 (SWIR1)
    // For Landsat 8/9, bands are B3 (Green), B6 (SWIR1)
    const greenBand = image.select(['B2', 'B3'], ['green', 'green']).first().rename('green');
    const swir1Band = image.select(['B5', 'B6'], ['swir1', 'swir1']).first().rename('swir1');

    const mndwi = image.expression(
      '(GREEN - SWIR1) / (GREEN + SWIR1)', {
        'GREEN': greenBand,
        'SWIR1': swir1Band
      }).rename('MNDWI');

    // Water is typically MNDWI > 0. A slightly higher threshold can help
    // distinguish open water from wet soil/vegetation.
    // Use a slightly conservative threshold.
    const water = mndwi.gt(0.2).rename('water');
    return image.addBands(mndwi).addBands(water);
  }

  // 2. Data Acquisition & Check - 1985
  let collection1 = ee.ImageCollection('LANDSAT/LT05/C02/T1_SR')
    .filterBounds(aoi)
    .filterDate(startYear1, endYear1)
    .map(maskL5Clouds)
    .map(addMNDWIAndWater);

  let imageCount1 = await collection1.size().getInfo();
  if (imageCount1 === 0) {
    console.log("No Landsat 5 data for 1985 after cloud masking.");
    console.log("C1");
    return;
  }
  let image1 = collection1.median();

  // Validate image1 for valid pixels
  let pixelCount1 = await image1.select('water').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('water').getInfo();

  if (pixelCount1 === 0) {
    console.log("No valid pixels for 1985 after masking.");
    console.log("C2");
    return;
  }

  // 3. Data Acquisition & Check - 2024 (or 2023 fallback)
  let collection2 = ee.ImageCollection('LANDSAT/LC09/C02/T1_SR')
    .filterBounds(aoi)
    .filterDate(startYear2, endYear2)
    .map(maskL89Clouds)
    .map(addMNDWIAndWater);

  let imageCount2 = await collection2.size().getInfo();
  let selectedYear2 = '2024';

  if (imageCount2 === 0) {
    console.log("No Landsat 9 data for 2024 after cloud masking. Trying Landsat 8 for 2023.");
    collection2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
      .filterBounds(aoi)
      .filterDate('2023-01-01', '2023-12-31')
      .map(maskL89Clouds)
      .map(addMNDWIAndWater);
    imageCount2 = await collection2.size().getInfo();
    selectedYear2 = '2023';
  }

  if (imageCount2 === 0) {
    console.log(`No Landsat data for ${selectedYear2} after cloud masking.`);
    console.log("C1");
    return;
  }
  let image2 = collection2.median();

  // Validate image2 for valid pixels
  let pixelCount2 = await image2.select('water').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: scale,
    maxPixels: 1e9
  }).get('water').getInfo();

  if (pixelCount2 === 0) {
    console.log(`No valid pixels for ${selectedYear2} after masking.`);
    console.log("C2");
    return;
  }

  // Calculate total AOI area for ratio calculation
  const totalArea = aoi.area({'maxError': 1}).divide(1e6); // in km^2

  // 4. Calculation of Open Water Area
  const waterArea1 = image1.select('water').multiply(ee.Image.pixelArea()).divide(1e6) // convert to km^2
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    }).get('water').getInfo();

  const waterArea2 = image2.select('water').multiply(ee.Image.pixelArea()).divide(1e6) // convert to km^2
    .reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: aoi,
      scale: scale,
      maxPixels: 1e9
    }).get('water').getInfo();

  // 5. Validation & Final Answer
  if (waterArea1 === null || waterArea2 === null) {
    console.log("Calculation of water area resulted in null.");
    console.log("C3");
    return;
  }

  const proportionWater1 = waterArea1 / totalArea.getInfo();
  const proportionWater2 = waterArea2 / totalArea.getInfo();

  // "relative to wetland areas" is interpreted as the proportion of open water within the AOI.
  // If the proportion of open water increases, it implies a decrease in other land covers (including wetlands)
  // within the AOI, effectively meaning an increase relative to them.

  console.log(`1985 Images: ${imageCount1}, Pixels: ${pixelCount1}`);
  console.log(`${selectedYear2} Images: ${imageCount2}, Pixels: ${pixelCount2}`);
  console.log(`Total AOI Area: ${totalArea.getInfo().toFixed(2)} km^2`);
  console.log(`1985 Open Water Area: ${waterArea1.toFixed(2)} km^2 (${(proportionWater1 * 100).toFixed(2)}%)`);
  console.log(`${selectedYear2} Open Water Area: ${waterArea2.toFixed(2)} km^2 (${(proportionWater2 * 100).toFixed(2)}%)`);

  const hasIncreased = proportionWater2 > proportionWater1;

  if (hasIncreased) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
